function UIActionImpressionDialog:FillSelf()
    local vo = ActionUtils.GetRegionPrimaryMapVo(self._mapId)
    if vo then
        CfUtils.FillText(self.TxtNameBlue, vo.name)
        CfUtils.FillText(self.TxtNamePuple, vo.name)
        CfUtils.FillText(self.TxtNameWhite, vo.name)
        
        CfUtils.FillImage(self.ImgAreamap, vo.mapIcon)
    end
    CfUtils.FillText(self.TxtLevel_Old1, self._targetLv - 1)
    CfUtils.FillText(self.TxtLevel_Old2, self._targetLv - 1)
    CfUtils.FillText(self.TxtLevel_Old3, self._targetLv - 1)

    CfUtils.FillText(self.TxtLevel_New1, self._targetLv)
    CfUtils.FillText(self.TxtLevel_New2, self._targetLv)
    CfUtils.FillText(self.TxtLevel_New3, self._targetLv)

    self:FillRewards()
end

function UIActionImpressionDialog:FillRewards()
    local id = ActionUtils.GetRegionLikabilityId(self._mapId, self._targetLv)
    local vo = ActionUtils.GetRegionLikabilityVo(id)
    if not vo then
        return
    end
    local t = ActionUtils.GetAllShowReward(vo.levelUpExplain)
    --print('--->>', table.dump(t, false, 2))
    ---处理第一个格子，是否存在商店的逻辑
    local shopGo = self["Cell"..1]
    if t['2'] and table.count(t['2']) > 0 then
        local str = localize('_name_区域商店', {_name_ = vo.name})
        local types = {}
        for _, v in pairs(t['2']) do
            if not types[tostring(v.unlockType2)] then
                types[tostring(v.unlockType2)] = 1
                if checkNumber(v.unlockType2) == 1 then
                    str = str .. localize('[材料类]')
                elseif checkNumber(v.unlockType2) == 2 then
                    if string.find(str, '材料类') then
                        str = str .. string.format_color_tag(localize('和[食材类]'), '#ff1baf')
                    else
                        str = str .. string.format_color_tag(localize('[食材类]'), '#ff1baf')
                    end
                end
            end
        end
        str = str .. localize('商品上新')
        CfUtils.FillText(shopGo.transform:Find('TextDesc'), str)
    else
        CfUtils.SetActive(shopGo, false)
    end
    local takeOutGo = self["Cell"..2]
    if t['3'] and table.count(t['3']) > 0 then
        local data = table.takeFirst(t['3'])
        CfUtils.FillText(takeOutGo.transform:Find('TextDesc'), tostring(data.describe))
    else
        CfUtils.SetActive(takeOutGo, false)
    end
    local takeOutLimitGo = self["Cell"..3]
    ----@type RegionPrimaryMapVo
    local mapVo = ActionUtils.GetRegionPrimaryMapVo(self._mapId)
    if mapVo then
        local lv, exp = ActionUtils.GetRegionalPointLikabilityLevel(mapVo.id)
        local timeLimitVos = CfUtils.GetCf(AutoIds.IdSetting6056,"TakeOutTimeLimitVo",true)
        ---@type TakeOutTimeLimitVo
        local timeLimitVo = timeLimitVos[checkNumber(mapVo.id)]
        if timeLimitVo then
            local limit = checkNumber(timeLimitVo.takeOutNum[lv])
            local text = localize('每日可送外卖上限提升至 +_num_', {_num_ = string.format_color_tag(limit, "#ff1baf")})
            CfUtils.FillText(takeOutLimitGo.transform:Find('TextDesc'), text)
        end
    end

    --for i = 1, 3 do
    --    local go = self["Cell"..i]
    --    local data = t[checkString(i)]
    --
    --    self:FillReward(go, data, checkString(i))
    --end
end

function UIActionImpressionDialog:FillReward(go, data, type)
    if not go then
        return
    end
    local scrollViewGo = go.transform:Find("Content")
    local emptyNodeGo = go.transform:Find("EmptyNode")

    if not data then
        CfUtils.SetActive(scrollViewGo, false)
        CfUtils.SetActive(emptyNodeGo, true)
        return
    else
        CfUtils.SetActive(scrollViewGo, true)
        CfUtils.SetActive(emptyNodeGo, false)
    end

    if checkNumber(type) == 1 then
        self:FillQuest(scrollViewGo, data, type)
    elseif checkNumber(type) == 2 then
        self:FillStore(scrollViewGo, data, type)
    elseif checkNumber(type) == 3 then
        self:FillSalout(scrollViewGo, data, type)
    end
end

function UIActionImpressionDialog:FillQuest(go, data, type)
    if not go or not data then
        return
    end

    local parGo = go
    local childGo = parGo.transform:Find("Item1")

    for i = 1, parGo.childCount do 
        local go = parGo.transform:GetChild(i - 1)
        CfUtils.SetActive(go, false)
    end

    local t = {}
    for k, v in pairs(data) do
        local cellGo = parGo.transform:Find("go"..k)
        if not cellGo then
            cellGo = CfUtils.InstantiateGo(childGo, parGo)
            cellGo.name = "go"..k
        end
        CfUtils.SetActive(cellGo, true)

        local vo = QuestConfMgr:GetInstance():GetQuestVoById(v.parameter)
        CfUtils.FillText(cellGo.transform:Find("Text2"), localize("难度")..vo.label)

        vo = ActionUtils.GetRegionSecondaryMapVo(vo.pointID)
        CfUtils.FillText(cellGo.transform:Find("Text1"), vo.name)
    end
end

function UIActionImpressionDialog:FillStore(go, data, type)
    if not go or not data then
        return
    end

    local parGo = go
    local childGo = parGo.transform:Find("Item1")

    for i = 1, parGo.childCount do 
        local go = parGo.transform:GetChild(i - 1)
        CfUtils.SetActive(go, false)
    end

    local t = {
        {
            desc = localize("[食材类]"),
            isShow = false
        },
        {
            desc = localize("[材料类]"),
            isShow = false
        }
    }
    for k, v in pairs(data) do
        if checkNumber(v.unlockType2) == 1 then
            t[2].isShow = false
        else
            t[1].isShow = true
        end
    end

    for k, v in pairs(t) do
        local cellGo = parGo.transform:Find("go"..k)
        if not cellGo then
            cellGo = CfUtils.InstantiateGo(childGo, parGo)
            cellGo.name = "go"..k
        end
        CfUtils.SetActive(cellGo, true)

        CfUtils.FillText(cellGo.transform:Find("Text1"), v.desc)
        CfUtils.FillText(cellGo.transform:Find("Text2"), localize("商品上新"))
    end
end

function UIActionImpressionDialog:FillSalout(go, data, type)
    if not go or not data then
        return
    end

    local parGo = go
    local child1Go = parGo.transform:Find("Item1")
    local child2Go = parGo.transform:Find("Item2")
    local child3Go = parGo.transform:Find("Item3")

    local str = data[1].describe
    local t = CfUtils.Split(str)
    CfUtils.SetActive(child1Go, table.count(t) > 0)
    CfUtils.FillText(child1Go.transform:Find("Text2"), localize("[新订单位]"))

    CfUtils.SetActive(child2Go, table.count(t) > 1)
    CfUtils.FillText(child2Go.transform:Find("Text1"), localize("订单"))
    CfUtils.FillText(child2Go.transform:Find("Text2"), localize("[基础收益提升]"))

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(data[1].parameter)
    if not vo then
        CfUtils.SetActive(child3Go, false)
    else
        CfUtils.SetActive(child3Go, true)
        CfUtils.RefeshGoodGo2(child3Go.transform:Find("GoodNode"), vo.id, nil, nil, nil, function()
            GameUtils.ShowCommonTipsBoard(child3Go.transform:Find("GoodNode"), vo.name, vo.desc, vo.quality, vo.id)
        end)

        local _go = CfUtils.InstantiateGo(child2Go, parGo)
        CfUtils.SetActive(_go, true)
        CfUtils.SetActive(_go.transform:Find("Text1"), false)

        CfUtils.FillText(_go.transform:Find("Text2"), localize("[概率出现]]"))
    end
end

function UIActionImpressionDialog:OnBtnBack()
    UIModule.CloseDialog(self.controller)
    if self._cb then
        self._cb()
    end
end

function UIActionImpressionDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._mapId = checkNumber(argument.id)  
        self._targetLv = checkNumber(argument.targetLv)  
        self._cb = argument.cb

        self:InitData()
        self:FillSelf()
    end))
    return coWait
end

function UIActionImpressionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActionImpressionDialog
